<script setup lang="ts">
import type { BsFinancialAccountCopy, BsFinancialAccountForm, BsAccountEditorView } from '../types/financialAccountsPresentation'
defineProps<{ copy: BsFinancialAccountCopy; view: BsAccountEditorView }>()
const form = defineModel<BsFinancialAccountForm>('form', { required: true })
const emit = defineEmits<{ close: []; save: [] }>()
function field<K extends keyof BsFinancialAccountForm>(key: K, value: BsFinancialAccountForm[K]) { form.value = { ...form.value, [key]: value } }
</script>
<template>
 <BsRecordActionDialog :visible="view.visible" :title="view.title" size="md" :dirty="view.dirty" :pending="view.pending" :error="view.error" :submit-label="copy.save" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('close') }" @submit="emit('save')">
  <BsUsageMeter v-if="!view.editing && view.usage" compact :item="view.usage"/><BsFloatingField :label="copy.name"><BsInput id="account-name" :model-value="form.name" required @update:model-value="field('name', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.code"><BsInput id="account-code" :model-value="form.code" dir="ltr" @update:model-value="field('code', String($event ?? ''))"/></BsFloatingField>
  <BsFloatingField :label="copy.role"><BsSelect id="account-role" :label="copy.role" :model-value="form.accountRole" :disabled="view.editing" aria-describedby="account-role-help" :options="view.roles" option-label="label" option-value="value" native @update:model-value="field('accountRole', $event as BsFinancialAccountForm['accountRole'])"/></BsFloatingField><BsText id="account-role-help" size="sm" tone="muted">{{ copy.roleHint }}</BsText>
  <BsFloatingField v-if="form.accountRole === 'control' && !view.editing" :label="copy.subledger"><BsSelect id="control-subledger-type" :label="copy.subledger" :model-value="form.controlSubledgerType" required :options="view.subledgers" option-label="label" option-value="value" native @update:model-value="field('controlSubledgerType', $event as BsFinancialAccountForm['controlSubledgerType'])"/></BsFloatingField><BsText v-if="form.accountRole === 'control'" size="sm" tone="muted">{{ copy.directBlocked }}</BsText><BsText v-if="view.bindingLocked" size="sm" tone="muted">{{ copy.bindingHint }}</BsText>
  <template v-if="!view.editing"><BsFloatingField :label="copy.type"><BsSelect id="account-type" :label="copy.type" :model-value="form.type" :disabled="form.accountRole === 'control'" :options="view.types" option-label="label" option-value="value" native @update:model-value="field('type', String($event))"/></BsFloatingField><BsFloatingField :label="copy.subtype"><BsSelect id="account-subtype" :label="copy.subtype" :model-value="form.subtype" :disabled="form.accountRole === 'control'" :options="view.subtypes" option-label="label" option-value="value" native @update:model-value="field('subtype', String($event))"/></BsFloatingField><BsFloatingField v-if="view.multiCurrency" :label="copy.currency"><BsSelect id="account-currency" :label="copy.currency" :model-value="form.currency" :options="view.currencies" option-label="label" option-value="value" native @update:model-value="field('currency', String($event))"/></BsFloatingField><BsText v-else size="sm" tone="muted">{{ copy.multiCurrency }}</BsText><BsFloatingField :label="copy.parent"><BsSelect id="account-parent" :label="copy.parent" :model-value="form.parentAccountId" :options="view.parents" option-label="label" option-value="value" native @update:model-value="field('parentAccountId', String($event))"/></BsFloatingField></template><BsText v-else-if="view.parentName" size="sm" tone="muted">{{ copy.parent }}: {{ view.parentName }}</BsText>
  <template v-if="form.accountRole !== 'group'"><BsFloatingField :label="copy.normal"><BsSelect id="account-normal-balance" :label="copy.normal" :model-value="form.normalBalance" :disabled="view.natureLocked || form.accountRole === 'control'" aria-describedby="account-nature-help" :options="view.natures" option-label="label" option-value="value" native @update:model-value="field('normalBalance', $event as 'debit' | 'credit')"/></BsFloatingField><BsText id="account-nature-help" size="sm" tone="muted">{{ copy.natureHint }}</BsText><BsFloatingField v-if="form.accountRole === 'posting'" :label="copy.contra"><BsSelect id="account-contra" :label="copy.contra" :model-value="form.contraAccountId" :disabled="view.natureLocked" aria-describedby="account-contra-help" :options="view.contras" option-label="label" option-value="value" native @update:model-value="field('contraAccountId', String($event))"/></BsFloatingField><BsText v-if="form.accountRole === 'posting'" id="account-contra-help" size="sm" tone="muted">{{ copy.contraHint }}</BsText><BsText v-if="view.natureLocked" size="sm" tone="muted">{{ copy.natureLocked }}</BsText></template>
 </BsRecordActionDialog>
</template>
